app RezoAnon

# ─────────────────────────────────────────────────────────────────────
# COMPLETE SOCIAL NETWORK — consolidates all the social examples:
#   • public posts with an ANONYMOUS author generated by the server (never
#     supplied by the client);
#   • likes shown as CATEGORIES (few / popular / viral) rather than as an
#     exact number;
#   • post SCORE that drops on a report (a single report per account and
#     per post);
#   • PRIVATE messages reachable by the sender and the recipient only;
#   • public comments, editable by their author only.
# The feed shows up already populated thanks to the demo data.
# ─────────────────────────────────────────────────────────────────────

entity Member
    name: String

entity Post
    content: Text
    author: String
    status: String
    likes: Integer
    dislikes: Integer
    reposts: Integer
    score: Integer

entity Comment
    content: Text

entity Like
    note: String

entity Dislike
    note: String

entity Repost
    note: String

entity Report
    reason: String

entity PrivateMessage
    content: Text
    recipient_id: Integer

relation Member hasMany Post
# ORDER MATTERS: the relation to the actor first, otherwise the
# 'post_id'
# column — targeted by 'increments' — would leave the INSERT and
# 'oncePer'
# would apply to a column that is always NULL (refused at compile time
# since
# point 116).
relation Member hasMany Like
relation Post hasMany Like
relation Post hasMany Dislike
relation Post hasMany Repost
relation Post hasMany Comment
relation Member hasMany Comment
relation Member hasMany Report
relation Post hasMany Report
relation Member hasMany PrivateMessage

actor Member selfRegister

# Moderator: provisioned offline (manage.py), they READ and DELETE every
# private message — the supervisor role above accessibleBy (brick 23).
actor Moderator

capability auth

# Posts public UNDER CONDITION (brick 27): a post hidden by moderation stops
# being readable, including through its direct URL. The moderator still sees
# it — otherwise hiding would mean losing — and the author finds their own.
rule Post.status oneOf "published", "hidden"
rule Post.Read publicWhen status "published"
rule Post.Read sharedBy Moderator
rule Post.author generated

# Likes are shown as categories (brick 5).
rule Post.likes categorized: "confidentiel" below 10, "populaire" below 100, "viral" otherwise

# Twitter-like reactions: like, dislike and repost raise the counters; a
# report lowers the targeted post's score. It targets a POST, not a member:
# 'Member' is also the actor, its records are tied to no account, and the
# compiler refuses a counter on them (issue #89). The reporting account is
# linked through the first relation, as for Like.
# Brick 28: an account likes each post only ONCE — uniqueness rests on a
# composite index (account + post), not on a fingerprint supplied by the
# client.
rule Like.Create oncePer Member, Post
rule Like.Create increments Post.likes by 1
rule Dislike.Create increments Post.dislikes by 1
rule Repost.Create increments Post.reposts by 1
rule Report.Create oncePer Member, Post
rule Report.Create decrements Post.score by 10

# Comments publicly readable, editable by their author only.
rule Comment.Read public
rule Comment.Update ownedBy Member
rule Comment.Delete ownedBy Member

# Private messaging: sender (member_id auto) AND recipient only.
rule PrivateMessage.Read accessibleBy member_id, recipient_id
rule PrivateMessage.Delete accessibleBy member_id, recipient_id
# The moderator supervises both: they see and delete every message.
rule PrivateMessage.Read sharedBy Moderator
rule PrivateMessage.Delete sharedBy Moderator

workflow Onboard for Member
    Create Member

workflow Publish for Member
    Create Post
    Read Post

workflow Interact for Member
    Create Like
    Create Dislike
    Create Repost
    Create Report

workflow Discuss for Member
    Create Comment
    Read Comment
    Update Comment
    Delete Comment

workflow DirectMessage for Member
    Create PrivateMessage
    Read PrivateMessage
    Delete PrivateMessage

workflow Moderate for Moderator
    Read PrivateMessage
    Delete PrivateMessage
    Read Post
    Update Post

# Demo feed: public posts already liked (varied categories). The author
# shown
# will be the generated anonymous pseudonym, not these values — the
# 'author'
# field is 'generated', so the seed does not fill it.
seed Post
    content: "Premier jour sur RezoAnon. L'anonymat change vraiment la façon de s'exprimer.", status: "published", score: 100, likes: 4
    content: "Astuce : les likes ne montrent qu'une catégorie, pas un score exact. Moins de course aux chiffres.", status: "published", score: 100, likes: 42
    content: "Ce post part pour devenir viral, on dirait. Merci à tous !", status: "published", score: 100, likes: 230
    content: "Question ouverte : préférez-vous l'anonymat total ou un pseudonyme stable ?", status: "published", score: 100, likes: 17
    content: "Le score d'un post baisse quand il est signalé — ça calme les trolls.", status: "published", score: 100, likes: 8

landing
    brief: "RezoAnon est un réseau social où les posts sont publics mais les auteurs restent anonymes, les likes s'affichent en catégories, et les signalements protègent la communauté."
